@icontract.snapshot(lambda self: self.host_port, name="old_host_port")
@icontract.snapshot(lambda self: adb.list_occupied_adb_ports(), name="old_occupied_ports")
@icontract.snapshot(lambda self: getattr(getattr(self._device, "adb", None), "mock_forward_func", None), name="old_mock_forward")
@icontract.ensure(lambda OLD, self: (not OLD.old_host_port) or self.host_port is None)
@icontract.ensure(lambda OLD, self: (not OLD.old_host_port) or self.host_port is None)
@icontract.ensure(
    lambda OLD, self:
    (
        # If there was no host_port before, the method must not have changed it.
        (not OLD.old_host_port) or self.host_port is None
    )
)
@icontract.ensure(
    lambda OLD, self:
    (
        # If there was a host_port and it was reported as forwarded before the call,
        # then the adb forward mock must have been invoked exactly once with the
        # expected remove command for that host port.
        (not (OLD.old_host_port and OLD.old_host_port in OLD.old_occupied_ports))
        or (
            getattr(getattr(self._device, "adb", None), "mock_forward_func", None)
            is not None
            and getattr(self._device.adb.mock_forward_func, "call_count", 0) == 1
            and getattr(self._device.adb.mock_forward_func, "call_args_list", [])[0][0]
            == (["--remove", f"tcp:{OLD.old_host_port}"],)
        )
    )
)
@icontract.ensure(
    lambda OLD, self:
    (
        # If there was a host_port and it was NOT reported as forwarded before the
        # call, then no adb forward call should have been made.
        (not (OLD.old_host_port and OLD.old_host_port not in OLD.old_occupied_ports))
        or (
            getattr(getattr(self._device, "adb", None), "mock_forward_func", None)
            is None
            or getattr(self._device.adb.mock_forward_func, "call_count", 0) == 0
        )
    )
)
